/*
===========================================================================

Filmic's desaturation cube, flattened.

The stage between the log encode and the contrast curve.  Near the top of
the log range it pulls a saturated colour toward white instead of letting
one channel clip: a fully saturated red at 0.75 of the range comes back
with its other channels at 0.465, at 0.906 they are at 0.803, and at the
top the colour is white.  Greys are untouched - the neutral axis matches
identity to 1.8e-04.

Taken from Blender, which distributes it as part of a GPL work; that is
where the licence to redistribute comes from.  Blender downsampled it
from Sobotka's original 65 cube to 33 themselves, with a note in the file
saying so.  This is their 33 version, quantised to 16 bits per channel.

  Filmic Dynamic Range LUT crafted by Troy James Sobotka.
  Taken from Blender (GNU GPL), release/datafiles/colormanagement/filmic/.

Stored as a 2D atlas rather than a 3D texture: the 33 blue slices are laid
side by side, so the texel for (r, g, b) is at x = b*33 + r, y = g, and
the texture is 1089 by 33.  A 3D texture would be the obvious choice and
is the wrong one here for two reasons - GLES2 has none, and the offscreen
harness this work is verified against cannot call glTexImage3D at all, so
a 3D path would be the one piece of GL in this feature that ships
unverified.  The flattened upload was checked on a driver by reading the texture back
and comparing it against this array, rather than by asking whether the
upload call errored.  That distinction cost a debugging round: a row of
this atlas is 6534 bytes at sixteen bits and 3267 at eight, neither a
multiple of the four GL_UNPACK_ALIGNMENT defaults to, so the first
version uploaded without error and arrived sheared.  27219 texels wrong,
and no GL error anywhere.  "The call succeeded" and "the data is right"
are separate questions.

The cost is doing the blue interpolation by hand - two fetches a slice
apart, mixed by the fractional part - which is a handful of instructions
against a stage that would otherwise not run at all on half the targets.

===========================================================================
*/

